function loopNext(dpmOj, parentId, nameOrg) {
    const id = crypto.randomUUID();
    const result = {
        "name": dpmOj.department_name_eng,
        "mamber": dpmOj.member_list[0] ,
        "id": id,
        "parentId": parentId
    }
    const targetGroup = arrDpm.find(item => item.name === nameOrg);
    if (targetGroup) {
        targetGroup.orgs.push(result);
    }
    // arrDpm.push(result)
    const nextDpm = dpmOj.next_department_list
    if (nextDpm != null) {
        for (let item of nextDpm) {
            loopNext(item, id, nameOrg)
        }
    } else {
        for (let member of dpmOj.member_list) {
            if(member.department_role == 'member') {
                if (targetGroup) {
                    targetGroup.orgs.push(
                        {
                            "name": 'member',
                            mamber: member,
                            "id": member.employee_no,
                            "parentId": id,
                        }
                    );
                }
            }
        }
    }
}
let arrDpm = []
for (let dpmOj of orgSaleRaw) {
    const nameOrg = dpmOj.department_name_eng
    arrDpm.push({
        name: nameOrg,
        orgs: []
    })
    loopNext(dpmOj, '', nameOrg)
}
console.log(arrDpm)
let selectedDept = ref(arrDpm[0])
let orgChartData = ref(arrDpm[0].orgs)
let orgChartKey = ref(0)
// loopNext(orgSaleRaw, '')


const initVue3OrgChart = ({api}) => {
     vocApi.value = api;
}
const onSelectionChange = async () =>{
    const newvalue = selectedDept.value.orgs
    orgChartData.value = newvalue
    orgChartKey.value++
    await nextTick();
}
